def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        return 0
    if m == 0:
        return 1

    # dp[i][j] = number of ways to be at student j after i passes
    # Students are numbered 0 to n-1, starting at student 0
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            # The ball can come from the left neighbor or the right neighbor
            left_neighbor = (j - 1) % n
            right_neighbor = (j + 1) % n
            dp[i][j] = dp[i - 1][left_neighbor] + dp[i - 1][right_neighbor]

    return dp[m][0]

